package com.hiretrack.controller;import com.hiretrack.entity.JobApplication;import com.hiretrack.repository.ApplicationRepository;import com.hiretrack.service.CurrentUser;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/applications")public class ApplicationController{private final ApplicationRepository repo;private final CurrentUser current;public ApplicationController(ApplicationRepository r,CurrentUser c){repo=r;current=c;}
public record Request(String companyName,String jobRole,String jobType,String location,String jobLink,BigDecimal salary,String status,LocalDate appliedDate,LocalDate deadline,String description){}
private Map<String,Object> dto(JobApplication a){Map<String,Object> m=new LinkedHashMap<>();m.put("id",a.getId());m.put("companyName",a.getCompanyName());m.put("jobRole",a.getJobRole());m.put("jobType",a.getJobType());m.put("location",a.getLocation());m.put("jobLink",a.getJobLink());m.put("salary",a.getSalary());m.put("status",a.getStatus());m.put("appliedDate",a.getAppliedDate());m.put("deadline",a.getDeadline());m.put("description",a.getDescription());m.put("createdAt",a.getCreatedAt());return m;}
private void fill(JobApplication a,Request r){a.setCompanyName(r.companyName());a.setJobRole(r.jobRole());a.setJobType(r.jobType());a.setLocation(r.location());a.setJobLink(r.jobLink());a.setSalary(r.salary());a.setAppliedDate(r.appliedDate());a.setDeadline(r.deadline());a.setDescription(r.description());}
private JobApplication owned(Long id){return repo.findByIdAndUserId(id,current.get().getId()).orElseThrow(()->new NoSuchElementException("Application not found"));}
@GetMapping public List<Map<String,Object>> all(){return repo.findAllByUserIdOrderByCreatedAtDesc(current.get().getId()).stream().map(this::dto).toList();}
@PostMapping public ResponseEntity<?> create(@RequestBody Request r){if(r.companyName()==null||r.companyName().isBlank()||r.jobRole()==null||r.jobRole().isBlank())return ResponseEntity.badRequest().body(Map.of("message","Company and role are required"));JobApplication a=new JobApplication();a.setUser(current.get());fill(a,r);a.setStatus(r.status()==null?"APPLIED":r.status());return ResponseEntity.ok(dto(repo.save(a)));}
@GetMapping("/{id}")public Map<String,Object> one(@PathVariable Long id){return dto(owned(id));}
@PutMapping("/{id}")public Map<String,Object> update(@PathVariable Long id,@RequestBody Request r){JobApplication a=owned(id);fill(a,r);if(r.status()!=null)a.setStatus(r.status());return dto(repo.save(a));}
@PatchMapping("/{id}/status")public Map<String,Object> status(@PathVariable Long id,@RequestBody Map<String,String> b){String s=b.get("status");if(!Set.of("WISHLIST","APPLIED","ASSESSMENT","INTERVIEW","OFFER","REJECTED","WITHDRAWN").contains(s))throw new IllegalArgumentException("Invalid status");JobApplication a=owned(id);a.setStatus(s);return dto(repo.save(a));}
@DeleteMapping("/{id}")public ResponseEntity<?> delete(@PathVariable Long id){repo.delete(owned(id));return ResponseEntity.noContent().build();}}